//! 🧯️ A fault-only receiver retains bytes from the authenticated ActorFailure protocol.
use semio_framework_job::{OriginalNativeRecipientIdentity,OriginalNativeRetirement,OriginalTurnFailure,StepContext};
use semio_framework_value::{RetainedCloneProgress,ValueError,ValueRefusalKind};
use std::mem::{ManuallyDrop,size_of};

/// 🎟️ The actual failed producer seals the same-Source fault recipient.
pub struct ActorFailurePermit{recipient:OriginalNativeRecipientIdentity,binding:semio_framework_job::OriginalSourceBinding,producer:OriginalNativeRecipientIdentity,reference:semio_framework_actor::ActorFailureCallReference}
impl ActorFailurePermit{pub fn issue<T:OriginalNativeRetirement>(reference:&semio_plugin_host_guest_runtime::GuestActorFailureCallReference,producer:&semio_framework_job::OriginalNativeBorrowed<'_,T>,recipient:OriginalNativeRecipientIdentity,cx:&StepContext<'_>)->Result<Self,OriginalTurnFailure>{producer.validate_context(cx)?;recipient.validate_context(cx)?;let producer=producer.recipient_identity();let reference=reference.reference_for(producer,cx)?;Ok(Self{recipient,producer,reference,binding:semio_framework_job::OriginalSourceBinding::borrow(cx)})}pub fn proves(&self,recipient:OriginalNativeRecipientIdentity,cx:&StepContext<'_>)->bool{cx.original_retirement_active()&&self.recipient==recipient&&self.binding.matches(cx)&&recipient.validate_context(cx).is_ok()&&self.producer.validate_context(cx).is_ok()}pub fn reference(&self)->semio_framework_actor::ActorFailureCallReference{self.reference}pub fn producer(&self)->OriginalNativeRecipientIdentity{self.producer}}
pub struct ActorFailureHome{bytes:ManuallyDrop<Vec<u8>>,recipient:Option<OriginalNativeRecipientIdentity>,expected:Option<usize>,sealed:bool,reference:Option<semio_framework_actor::ActorFailureCallReference>,producer:Option<OriginalNativeRecipientIdentity>}
impl ActorFailureHome{
 pub fn empty()->Self{Self{bytes:ManuallyDrop::new(Vec::new()),recipient:None,expected:None,sealed:false,reference:None,producer:None}}
 fn verify(&self,permit:&ActorFailurePermit,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.reference!=Some(permit.reference)||self.producer!=Some(permit.producer)||self.recipient.is_none_or(|recipient|!permit.proves(recipient,cx)){return Err(refused().into())}Ok(())}
 pub fn bind_step(&mut self,recipient:OriginalNativeRecipientIdentity,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !permit.proves(recipient,cx){return Err(refused().into())}if let Some(existing)=self.recipient{return if existing==recipient&&self.reference==Some(permit.reference)&&self.producer==Some(permit.producer){Ok(true)}else{Err(refused().into())}}let bytes=2*size_of::<Option<OriginalNativeRecipientIdentity>>()+size_of::<Option<semio_framework_actor::ActorFailureCallReference>>();if !pay_many(cx,3,bytes,0)?{return Ok(false)}self.recipient=Some(recipient);self.producer=Some(permit.producer);self.reference=Some(permit.reference);Ok(true)}
 pub fn prepare(&mut self,permit:&ActorFailurePermit,length:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.verify(permit,cx)?;if length>semio_framework_job_payload::JOB_PAYLOAD_OPERATION_BYTES{return Err(refused().into())}if let Some(expected)=self.expected{return if expected==length{Ok(true)}else{Err(refused().into())}}let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items<3||grant.maximum_depth==0||grant.maximum_capacity_bytes<length||grant.maximum_copy_bytes<size_of::<Option<usize>>()+2*size_of::<usize>()||cx.fuel_remaining()<3{return Ok(false)}self.bytes.try_reserve_exact(length).map_err(|_|refused())?;self.expected=Some(length);cx.consume_retained(RetainedCloneProgress{copied_items:3,copied_bytes:size_of::<Option<usize>>()+2*size_of::<usize>(),retained_capacity_bytes:self.bytes.capacity(),..Default::default()})?;cx.consume_fuel(3);Ok(true)}
 pub fn append_page(&mut self,permit:&ActorFailurePermit,offset:usize,page:&[u8],cursor:&mut usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.verify(permit,cx)?;let expected=self.expected.ok_or_else(refused)?;if self.sealed||*cursor>page.len()||offset.checked_add(*cursor)!=Some(self.bytes.len())||offset.checked_add(page.len()).is_none_or(|end|end>expected){return Err(refused().into())}if *cursor==page.len(){return Ok(true)}let grant=cx.retained_grant();let metadata=2*size_of::<usize>();let count=(page.len()-*cursor).min(grant.maximum_copy_bytes.saturating_sub(metadata)).min(usize::try_from(cx.fuel_remaining().saturating_sub(2)).unwrap_or(usize::MAX));if cx.retirement_should_yield()||grant.maximum_items<3||grant.maximum_depth==0||count==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:3,copied_bytes:count+metadata,..Default::default()})?;cx.consume_fuel(u64::try_from(count).unwrap_or(u64::MAX)+2);self.bytes.extend_from_slice(&page[*cursor..*cursor+count]);*cursor+=count;Ok(*cursor==page.len())}
 pub fn seal(&mut self,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.verify(permit,cx)?;if self.sealed{return Ok(true)}if self.expected!=Some(self.bytes.len()){return Err(refused().into())}if !pay(cx,size_of::<bool>(),0)?{return Ok(false)}self.sealed=true;Ok(true)}
 pub fn bytes(&self)->Result<&[u8],ValueError>{if !self.sealed{return Err(refused())}Ok(&self.bytes)}
 pub fn sealed(&self)->bool{self.sealed}
}
impl OriginalNativeRetirement for ActorFailureHome{
 fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}if !self.bytes.is_empty(){if !pay(cx,size_of::<usize>(),0)?{return Ok(false)}self.bytes.clear();return Ok(false)}if self.bytes.capacity()!=0{let capacity=self.bytes.capacity();if !pay(cx,size_of::<Vec<u8>>(),capacity)?{return Ok(false)}drop(std::mem::take(&mut*self.bytes));return Ok(false)}if self.recipient.is_some()||self.expected.is_some()||self.reference.is_some()||self.producer.is_some()||self.sealed{let bytes=2*size_of::<Option<OriginalNativeRecipientIdentity>>()+size_of::<Option<usize>>()+size_of::<Option<semio_framework_actor::ActorFailureCallReference>>()+size_of::<bool>();if !pay_many(cx,5,bytes,0)?{return Ok(false)}self.recipient=None;self.expected=None;self.reference=None;self.producer=None;self.sealed=false;}Ok(true)}
 fn terminal_is_empty(&self)->bool{self.bytes.is_empty()&&self.bytes.capacity()==0&&self.recipient.is_none()&&self.expected.is_none()&&self.reference.is_none()&&self.producer.is_none()&&!self.sealed}
}
impl Drop for ActorFailureHome{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"actor failure receiver requires Source-funded retirement");if self.bytes.is_empty()&&self.bytes.capacity()==0{unsafe{ManuallyDrop::drop(&mut self.bytes)}}}}

/// 🧊️ An actual native borrow seals the unchanged complete fault extent.
pub struct ActorFailureSealed{native:Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>,reference:semio_framework_actor::ActorFailureCallReference,producer:OriginalNativeRecipientIdentity,binding:semio_framework_job::OriginalSourceBinding}
pub fn seal_actor_failure_step(mut home:semio_framework_job::OriginalNativeBorrowed<'_,ActorFailureHome>,native:&mut Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>,permit:&ActorFailurePermit,out:&mut Option<ActorFailureSealed>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{home.validate_context(cx)?;let recipient=home.recipient_identity();if out.is_some()||native.as_ref().is_none_or(|lease|lease.recipient_identity()!=recipient)||!permit.proves(recipient,cx){return Err(refused().into())}let value=home.value_mut();value.verify(permit,cx)?;if !value.sealed(){return Ok(false)}if !pay_many(cx,2,size_of::<Option<ActorFailureSealed>>()+size_of::<Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>>(),0)?{return Ok(false)}*out=Some(ActorFailureSealed{native:native.take(),reference:permit.reference,producer:permit.producer,binding:permit.binding});Ok(true)}
/// 📬️ Only the verified ActorFailure recipient can become this fault capsule.
pub struct ActorFailureCapsule{native:Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>,reference:semio_framework_actor::ActorFailureCallReference,producer:OriginalNativeRecipientIdentity,binding:semio_framework_job::OriginalSourceBinding}
impl ActorFailureCapsule{
 pub fn take_step(native:&mut Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<Option<Self>,OriginalTurnFailure>{let lease=native.as_mut().ok_or_else(refused)?;let recipient=lease.recipient_identity();if !permit.proves(recipient,cx){return Err(refused().into())}let mut sealed=false;if !lease.with_native(cx,|home,cx|{home.verify(permit,cx)?;sealed=home.sealed();Ok(())})?||!sealed||!pay(cx,size_of::<Self>(),0)?{return Ok(None)}Ok(Some(Self{native:native.take(),reference:permit.reference,producer:permit.producer,binding:permit.binding}))}
 pub fn take_sealed_into(sealed:&mut Option<ActorFailureSealed>,permit:&ActorFailurePermit,out:&mut Option<Self>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if out.is_some(){return Err(refused().into())}let proof=sealed.as_mut().ok_or_else(refused)?;let recipient=proof.native.as_ref().ok_or_else(refused)?.recipient_identity();if proof.reference!=permit.reference||proof.producer!=permit.producer||!proof.binding.matches(cx)||!permit.proves(recipient,cx){return Err(refused().into())}if !pay_many(cx,2,size_of::<Option<Self>>()+size_of::<Option<ActorFailureSealed>>(),0)?{return Ok(false)}let mut proof=sealed.take().ok_or_else(refused)?;*out=Some(Self{native:proof.native.take(),reference:permit.reference,producer:permit.producer,binding:permit.binding});Ok(true)}
 pub fn with_bytes(&mut self,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{self.native.as_mut().ok_or_else(refused)?.with_native(cx,|home,cx|receive(home.bytes()?,cx))}
 pub fn return_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{semio_framework_job::OriginalNativeLease::return_slot_step(&mut self.native,cx)}
 pub fn terminal_is_empty(&self)->bool{self.native.is_none()}pub fn qualifies(&self,permit:&ActorFailurePermit,cx:&StepContext<'_>)->bool{self.reference==permit.reference&&self.producer==permit.producer&&self.binding.matches(cx)&&self.native.as_ref().is_some_and(|lease|permit.proves(lease.recipient_identity(),cx))}
}
fn pay_many(cx:&mut StepContext<'_>,items:usize,bytes:usize,release:usize)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items<items||grant.maximum_copy_bytes<bytes||grant.maximum_release_bytes<release||grant.maximum_depth==0||cx.fuel_remaining()<items as u64{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:items,copied_bytes:bytes,released_bytes:release,..Default::default()})?;cx.consume_fuel(items as u64);Ok(true)}
fn pay(cx:&mut StepContext<'_>,bytes:usize,release:usize)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_release_bytes<release||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,released_bytes:release,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
fn refused()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"ActorFailure receiver requires its exact Source and verified recipient")}

#[path="📥️recipient/🦀️.rs"]mod recipient;
pub use recipient::{ActorFailureRecipient,ActorFailureRecipientHome,ActorFailureRecipientAccepted};

